import os
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _as_box(bounding_box: Any) -> Optional[Dict[str, float]]:
    if not bounding_box:
        return None
    result = {}
    for key in ("Left", "Top", "Width", "Height"):
        val = getattr(bounding_box, key, None)
        if val is None and isinstance(bounding_box, dict):
            val = bounding_box.get(key)
        if val is not None:
            result[key.lower()] = float(val)
    return result or None


def _geometry_to_dict(geometry: Any) -> Dict[str, Any]:
    if not geometry:
        return {}
    out: Dict[str, Any] = {}
    box = _as_box(getattr(geometry, "BoundingBox", None) or geometry.get("BoundingBox") if isinstance(geometry, dict) else None)
    if box:
        out["bounding_box"] = box

    polygon = getattr(geometry, "Polygon", None) or geometry.get("Polygon") if isinstance(geometry, dict) else None
    if polygon:
        points = []
        for p in polygon:
            x = getattr(p, "X", None) if not isinstance(p, dict) else p.get("X")
            y = getattr(p, "Y", None) if not isinstance(p, dict) else p.get("Y")
            if x is not None and y is not None:
                points.append({"x": float(x), "y": float(y)})
        if points:
            out["polygon"] = points
    return out


def _block_to_dict(block: Any) -> Dict[str, Any]:
    out: Dict[str, Any] = {
        "id": getattr(block, "Id", None) or block.get("Id") if isinstance(block, dict) else None,
        "block_type": getattr(block, "BlockType", None) or block.get("BlockType") if isinstance(block, dict) else None,
        "confidence": float(getattr(block, "Confidence", None) or block.get("Confidence") or 0.0) if (getattr(block, "Confidence", None) is not None or (isinstance(block, dict) and block.get("Confidence") is not None)) else None,
    }

    text = getattr(block, "Text", None) if not isinstance(block, dict) else block.get("Text")
    if text is not None:
        out["text"] = text

    page = getattr(block, "Page", None) if not isinstance(block, dict) else block.get("Page")
    if page is not None:
        out["page"] = int(page)

    geometry = getattr(block, "Geometry", None) if not isinstance(block, dict) else block.get("Geometry")
    geom_dict = _geometry_to_dict(geometry)
    if geom_dict:
        out["geometry"] = geom_dict

    relationships = getattr(block, "Relationships", None) if not isinstance(block, dict) else block.get("Relationships")
    if relationships:
        rels = []
        for rel in relationships:
            rel_type = getattr(rel, "Type", None) if not isinstance(rel, dict) else rel.get("Type")
            ids = getattr(rel, "Ids", None) if not isinstance(rel, dict) else rel.get("Ids")
            rels.append({"type": rel_type, "ids": list(ids or [])})
        out["relationships"] = rels

    return {k: v for k, v in out.items() if v is not None}


def _extract_tables(blocks: List[Any]) -> List[Dict[str, Any]]:
    block_map = {}
    for b in blocks:
        bid = getattr(b, "Id", None) if not isinstance(b, dict) else b.get("Id")
        if bid:
            block_map[bid] = b

    tables = []
    for b in blocks:
        btype = getattr(b, "BlockType", None) if not isinstance(b, dict) else b.get("BlockType")
        if btype != "TABLE":
            continue

        table = _block_to_dict(b)
        cells = []
        relationships = getattr(b, "Relationships", None) if not isinstance(b, dict) else b.get("Relationships")
        for rel in relationships or []:
            rel_type = getattr(rel, "Type", None) if not isinstance(rel, dict) else rel.get("Type")
            ids = getattr(rel, "Ids", None) if not isinstance(rel, dict) else rel.get("Ids")
            if rel_type == "CHILD":
                for cid in ids or []:
                    child = block_map.get(cid)
                    if not child:
                        continue
                    child_type = getattr(child, "BlockType", None) if not isinstance(child, dict) else child.get("BlockType")
                    if child_type == "CELL":
                        cell = _block_to_dict(child)
                        row = getattr(child, "RowIndex", None) if not isinstance(child, dict) else child.get("RowIndex")
                        col = getattr(child, "ColumnIndex", None) if not isinstance(child, dict) else child.get("ColumnIndex")
                        row_span = getattr(child, "RowSpan", None) if not isinstance(child, dict) else child.get("RowSpan")
                        col_span = getattr(child, "ColumnSpan", None) if not isinstance(child, dict) else child.get("ColumnSpan")
                        if row is not None:
                            cell["row_index"] = int(row)
                        if col is not None:
                            cell["column_index"] = int(col)
                        if row_span is not None:
                            cell["row_span"] = int(row_span)
                        if col_span is not None:
                            cell["column_span"] = int(col_span)
                        cells.append(cell)

        if cells:
            table["cells"] = cells
        tables.append(table)
    return tables


def extract_layout(document_bytes: bytes, feature_types: Optional[List[str]] = None, region_name: Optional[str] = None) -> Dict[str, Any]:
    """
    Extract OCR blocks, lines, and tables from a document using Amazon Textract.

    Args:
        document_bytes: Raw bytes of the document.
        feature_types: Textract feature types, defaults to ["TABLES", "FORMS"].
        region_name: AWS region name, optional.

    Returns:
        A dictionary with parsed blocks, lines, tables, and raw response metadata.
    """
    textract = boto3.client("textract", region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"))
    features = feature_types or ["TABLES", "FORMS"]

    try:
        response = textract.analyze_document(
            Document={"Bytes": document_bytes},
            FeatureTypes=features,
        )
    except (BotoCoreError, ClientError):
        response = textract.detect_document_text(
            Document={"Bytes": document_bytes},
        )

    blocks = response.get("Blocks", [])

    parsed_blocks = [_block_to_dict(b) for b in blocks]
    lines = [b for b in parsed_blocks if b.get("block_type") == "LINE"]
    words = [b for b in parsed_blocks if b.get("block_type") == "WORD"]
    tables = _extract_tables(blocks)

    return {
        "blocks": parsed_blocks,
        "lines": lines,
        "words": words,
        "tables": tables,
        "raw_response_metadata": {
            "document_metadata": response.get("DocumentMetadata", {}),
            "job_status": response.get("JobStatus"),
            "response_metadata": response.get("ResponseMetadata", {}),
        },
    }
